charset_normalizer.cd.coherence_ratio:
@lru_cache(maxsize=2048)
def coherence_ratio(decoded_sequence: str, threshold: float = 0.1, lg_inclusion: Optional[str] = None) -> CoherenceMatches:
    """
    Detect ANY language that can be identified in given sequence. The sequence will be analysed by layers.
    A layer = Character extraction by alphabets/ranges.
    """
    results: List[Tuple[(str, float)]] = []
    ignore_non_latin: bool = False
    sufficient_match_count: int = 0
    lg_inclusion_list = (lg_inclusion.split(',') if lg_inclusion is not None else [])
    if 'Latin Based' in lg_inclusion_list:
        ignore_non_latin = True
        lg_inclusion_list.remove('Latin Based')
    for layer in alpha_unicode_split(decoded_sequence):
        sequence_frequencies: TypeCounter[str] = Counter(layer)
        most_common = sequence_frequencies.most_common()
        character_count: int = sum((o for (c, o) in most_common))
        if character_count <= TOO_SMALL_SEQUENCE:
            continue
        popular_character_ordered: List[str] = [c for (c, o) in most_common]
        for language in (lg_inclusion_list or alphabet_languages(popular_character_ordered, ignore_non_latin)):
            ratio: float = characters_popularity_compare(language, popular_character_ordered)
            if ratio < threshold:
                continue
            elif ratio >= 0.8:
                sufficient_match_count += 1
            results.append((language, round(ratio, 4)))
            if sufficient_match_count >= 3:
                break
    return sorted(results, key=lambda x: x[1], reverse=True)

charset_normalizer.cd.alpha_unicode_spli:
def alpha_unicode_split(decoded_sequence: str) -> List[str]:
    """
    Given a decoded text sequence, return a list of str. Unicode range / alphabet separation.
    Ex. a text containing English/Latin with a bit a Hebrew will return two items in the resulting list;
    One containing the latin letters and the other hebrew.
    """
    layers: Dict[(str, str)] = {}
    for character in decoded_sequence:
        if character.isalpha() is False:
            continue
        character_range: Optional[str] = unicode_range(character)
        if character_range is None:
            continue
        layer_target_range: Optional[str] = None
        for discovered_range in layers:
            if is_suspiciously_successive_range(discovered_range, character_range) is False:
                layer_target_range = discovered_range
                break
        if layer_target_range is None:
            layer_target_range = character_range
        if layer_target_range not in layers:
            layers[layer_target_range] = character.lower()
            continue
        layers[layer_target_range] += character.lower()
    return list(layers.values())

charset_normalizer.cd.merge_coherence_ra:
def merge_coherence_ratios(results: List[CoherenceMatches]) -> CoherenceMatches:
    """
    This function merge results previously given by the function coherence_ratio.
    The return type is the same as coherence_ratio.
    """
    per_language_ratios: Dict[(str, List[float])] = {}
    for result in results:
        for sub_result in result:
            (language, ratio) = sub_result
            if language not in per_language_ratios:
                per_language_ratios[language] = [ratio]
                continue
            per_language_ratios[language].append(ratio)
    merge = [(language, round(sum(per_language_ratios[language]) / len(per_language_ratios[language]), 4)) for language in per_language_ratios]
    return sorted(merge, key=lambda x: x[1], reverse=True)

charset_normalizer.md.mess_ratio:
@lru_cache(maxsize=2048)
def mess_ratio(decoded_sequence: str, maximum_threshold: float = 0.2, debug: bool = False) -> float:
    """
    Compute a mess ratio given a decoded bytes sequence. The maximum threshold does stop the computation earlier.
    """
    detectors: List[MessDetectorPlugin] = [md_class() for md_class in MessDetectorPlugin.__subclasses__()]
    length: int = len(decoded_sequence) + 1
    mean_mess_ratio: float = 0.0
    if length < 512:
        intermediary_mean_mess_ratio_calc: int = 32
    elif length <= 1024:
        intermediary_mean_mess_ratio_calc = 64
    else:
        intermediary_mean_mess_ratio_calc = 128
    for (character, index) in zip(decoded_sequence + '\n', range(length)):
        for detector in detectors:
            if detector.eligible(character):
                detector.feed(character)
        if ((index > 0 and index % intermediary_mean_mess_ratio_calc == 0) or index == length - 1):
            mean_mess_ratio = sum((dt.ratio for dt in detectors))
            if mean_mess_ratio >= maximum_threshold:
                break
    if debug:
        for dt in detectors:
            print(dt.__class__, dt.ratio)
    return round(mean_mess_ratio, 3)

charset_normalizer.utils.identify_sig_or:
def identify_sig_or_bom(sequence: bytes) -> Tuple[(Optional[str], bytes)]:
    """
    Identify and extract SIG/BOM in given sequence.
    """
    for iana_encoding in ENCODING_MARKS:
        marks: Union[(bytes, List[bytes])] = ENCODING_MARKS[iana_encoding]
        if isinstance(marks, bytes):
            marks = [marks]
        for mark in marks:
            if sequence.startswith(mark):
                return (iana_encoding, mark)
    return (None, b'')

charset_normalizer.utils.cut_sequence_ch:
def cut_sequence_chunks(sequences: bytes, encoding_iana: str, offsets: range, chunk_size: int, bom_or_sig_available: bool, strip_sig_or_bom: bool, sig_payload: bytes, is_multi_byte_decoder: bool, decoded_payload: Optional[str] = None) -> Generator[(str, None, None)]:
    if (decoded_payload and is_multi_byte_decoder is False):
        for i in offsets:
            chunk = decoded_payload[i:i + chunk_size]
            if not chunk:
                break
            yield chunk
    else:
        for i in offsets:
            chunk_end = i + chunk_size
            if chunk_end > len(sequences) + 8:
                continue
            cut_sequence = sequences[i:i + chunk_size]
            if (bom_or_sig_available and strip_sig_or_bom is False):
                cut_sequence = sig_payload + cut_sequence
            chunk = cut_sequence.decode(encoding_iana, errors=('ignore' if is_multi_byte_decoder else 'strict'))
            if (is_multi_byte_decoder and i > 0 and sequences[i] >= 128):
                chunk_partial_size_chk: int = min(chunk_size, 16)
                if (decoded_payload and chunk[:chunk_partial_size_chk] not in decoded_payload):
                    for j in range(i, i - 4, -1):
                        cut_sequence = sequences[j:chunk_end]
                        if (bom_or_sig_available and strip_sig_or_bom is False):
                            cut_sequence = sig_payload + cut_sequence
                        chunk = cut_sequence.decode(encoding_iana, errors='ignore')
                        if chunk[:chunk_partial_size_chk] in decoded_payload:
                            break
            yield chunk

charset_normalizer.cd.encoding_languages:
@lru_cache()
def encoding_languages(iana_name: str) -> List[str]:
    """
    Single-byte encoding language association. Some code page are heavily linked to particular language(s).
    This function does the correspondence.
    """
    unicode_ranges: List[str] = encoding_unicode_range(iana_name)
    primary_range: Optional[str] = None
    for specified_range in unicode_ranges:
        if 'Latin' not in specified_range:
            primary_range = specified_range
            break
    if primary_range is None:
        return ['Latin Based']
    return unicode_range_languages(primary_range)

charset_normalizer.utils.any_specified_e:
def any_specified_encoding(sequence: bytes, search_zone: int = 4096) -> Optional[str]:
    """
    Extract using ASCII-only decoder any specified encoding in the first n-bytes.
    """
    if not isinstance(sequence, bytes):
        raise TypeError
    seq_len: int = len(sequence)
    results: List[str] = findall(RE_POSSIBLE_ENCODING_INDICATION, sequence[:min(seq_len, search_zone)].decode('ascii', errors='ignore'))
    if len(results) == 0:
        return None
    for specified_encoding in results:
        specified_encoding = specified_encoding.lower().replace('-', '_')
        encoding_alias: str
        encoding_iana: str
        for (encoding_alias, encoding_iana) in aliases.items():
            if encoding_alias == specified_encoding:
                return encoding_iana
            if encoding_iana == specified_encoding:
                return encoding_iana
    return None

charset_normalizer.cd.mb_encoding_langua:
@lru_cache()
def mb_encoding_languages(iana_name: str) -> List[str]:
    """
    Multi-byte encoding language association. Some code page are heavily linked to particular language(s).
    This function does the correspondence.
    """
    if (iana_name.startswith('shift_') or iana_name.startswith('iso2022_jp') or iana_name.startswith('euc_j') or iana_name == 'cp932'):
        return ['Japanese']
    if (iana_name.startswith('gb') or iana_name in ZH_NAMES):
        return ['Chinese', 'Classical Chinese']
    if (iana_name.startswith('iso2022_kr') or iana_name in KO_NAMES):
        return ['Korean']
    return []

charset_normalizer.api.from_bytes:
def from_bytes(sequences: bytes, steps: int = 5, chunk_size: int = 512, threshold: float = 0.2, cp_isolation: Optional[List[str]] = None, cp_exclusion: Optional[List[str]] = None, preemptive_behaviour: bool = True, explain: bool = False) -> CharsetMatches:
    """
    Given a raw bytes sequence, return the best possibles charset usable to render str objects.
    If there is no results, it is a strong indicator that the source is binary/not text.
    By default, the process will extract 5 blocs of 512o each to assess the mess and coherence of a given sequence.
    And will give up a particular code page after 20% of measured mess. Those criteria are customizable at will.

    The preemptive behavior DOES NOT replace the traditional detection workflow, it prioritize a particular code page
    but never take it for granted. Can improve the performance.

    You may want to focus your attention to some code page or/and not others, use cp_isolation and cp_exclusion for that
    purpose.

    This function will strip the SIG in the payload/sequence every time except on UTF-16, UTF-32.
    By default the library does not setup any handler other than the NullHandler, if you choose to set the 'explain'
    toggle to True it will alter the logger configuration to add a StreamHandler that is suitable for debugging.
    Custom logging format and handler can be set manually.
    """
    if not isinstance(sequences, (bytearray, bytes)):
        raise TypeError('Expected object of type bytes or bytearray, got: {0}'.format(type(sequences)))
    if explain:
        previous_logger_level: int = logger.level
        logger.addHandler(explain_handler)
        logger.setLevel(TRACE)
    length: int = len(sequences)
    if length == 0:
        logger.debug('Encoding detection on empty bytes, assuming utf_8 intention.')
        if explain:
            logger.removeHandler(explain_handler)
            logger.setLevel((previous_logger_level or logging.WARNING))
        return CharsetMatches([CharsetMatch(sequences, 'utf_8', 0.0, False, [], '')])
    if cp_isolation is not None:
        logger.log(TRACE, 'cp_isolation is set. use this flag for debugging purpose. limited list of encoding allowed : %s.', ', '.join(cp_isolation))
        cp_isolation = [iana_name(cp, False) for cp in cp_isolation]
    else:
        cp_isolation = []
    if cp_exclusion is not None:
        logger.log(TRACE, 'cp_exclusion is set. use this flag for debugging purpose. limited list of encoding excluded : %s.', ', '.join(cp_exclusion))
        cp_exclusion = [iana_name(cp, False) for cp in cp_exclusion]
    else:
        cp_exclusion = []
    if length <= chunk_size * steps:
        logger.log(TRACE, 'override steps (%i) and chunk_size (%i) as content does not fit (%i byte(s) given) parameters.', steps, chunk_size, length)
        steps = 1
        chunk_size = length
    if (steps > 1 and length / steps < chunk_size):
        chunk_size = int(length / steps)
    is_too_small_sequence: bool = len(sequences) < TOO_SMALL_SEQUENCE
    is_too_large_sequence: bool = len(sequences) >= TOO_BIG_SEQUENCE
    if is_too_small_sequence:
        logger.log(TRACE, 'Trying to detect encoding from a tiny portion of ({}) byte(s).'.format(length))
    elif is_too_large_sequence:
        logger.log(TRACE, 'Using lazy str decoding because the payload is quite large, ({}) byte(s).'.format(length))
    prioritized_encodings: List[str] = []
    specified_encoding: Optional[str] = (any_specified_encoding(sequences) if preemptive_behaviour else None)
    if specified_encoding is not None:
        prioritized_encodings.append(specified_encoding)
        logger.log(TRACE, 'Detected declarative mark in sequence. Priority +1 given for %s.', specified_encoding)
    tested: Set[str] = set()
    tested_but_hard_failure: List[str] = []
    tested_but_soft_failure: List[str] = []
    fallback_ascii: Optional[CharsetMatch] = None
    fallback_u8: Optional[CharsetMatch] = None
    fallback_specified: Optional[CharsetMatch] = None
    results: CharsetMatches = CharsetMatches()
    (sig_encoding, sig_payload) = identify_sig_or_bom(sequences)
    if sig_encoding is not None:
        prioritized_encodings.append(sig_encoding)
        logger.log(TRACE, 'Detected a SIG or BOM mark on first %i byte(s). Priority +1 given for %s.', len(sig_payload), sig_encoding)
    prioritized_encodings.append('ascii')
    if 'utf_8' not in prioritized_encodings:
        prioritized_encodings.append('utf_8')
    for encoding_iana in prioritized_encodings + IANA_SUPPORTED:
        if (cp_isolation and encoding_iana not in cp_isolation):
            continue
        if (cp_exclusion and encoding_iana in cp_exclusion):
            continue
        if encoding_iana in tested:
            continue
        tested.add(encoding_iana)
        decoded_payload: Optional[str] = None
        bom_or_sig_available: bool = sig_encoding == encoding_iana
        strip_sig_or_bom: bool = (bom_or_sig_available and should_strip_sig_or_bom(encoding_iana))
        if (encoding_iana in {'utf_16', 'utf_32'} and not bom_or_sig_available):
            logger.log(TRACE, 'Encoding %s wont be tested as-is because it require a BOM. Will try some sub-encoder LE/BE.', encoding_iana)
            continue
        try:
            is_multi_byte_decoder: bool = is_multi_byte_encoding(encoding_iana)
        except (ModuleNotFoundError, ImportError):
            logger.log(TRACE, 'Encoding %s does not provide an IncrementalDecoder', encoding_iana)
            continue
        try:
            if (is_too_large_sequence and is_multi_byte_decoder is False):
                str((sequences[:int(500000.0)] if strip_sig_or_bom is False else sequences[len(sig_payload):int(500000.0)]), encoding=encoding_iana)
            else:
                decoded_payload = str((sequences if strip_sig_or_bom is False else sequences[len(sig_payload):]), encoding=encoding_iana)
        except (UnicodeDecodeError, LookupError) as e:
            if not isinstance(e, LookupError):
                logger.log(TRACE, 'Code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
            tested_but_hard_failure.append(encoding_iana)
            continue
        similar_soft_failure_test: bool = False
        for encoding_soft_failed in tested_but_soft_failure:
            if is_cp_similar(encoding_iana, encoding_soft_failed):
                similar_soft_failure_test = True
                break
        if similar_soft_failure_test:
            logger.log(TRACE, '%s is deemed too similar to code page %s and was consider unsuited already. Continuing!', encoding_iana, encoding_soft_failed)
            continue
        r_ = range((0 if not bom_or_sig_available else len(sig_payload)), length, int(length / steps))
        multi_byte_bonus: bool = (is_multi_byte_decoder and decoded_payload is not None and len(decoded_payload) < length)
        if multi_byte_bonus:
            logger.log(TRACE, 'Code page %s is a multi byte encoding table and it appear that at least one character was encoded using n-bytes.', encoding_iana)
        max_chunk_gave_up: int = int(len(r_) / 4)
        max_chunk_gave_up = max(max_chunk_gave_up, 2)
        early_stop_count: int = 0
        lazy_str_hard_failure = False
        md_chunks: List[str] = []
        md_ratios = []
        try:
            for chunk in cut_sequence_chunks(sequences, encoding_iana, r_, chunk_size, bom_or_sig_available, strip_sig_or_bom, sig_payload, is_multi_byte_decoder, decoded_payload):
                md_chunks.append(chunk)
                md_ratios.append(mess_ratio(chunk, threshold))
                if md_ratios[-1] >= threshold:
                    early_stop_count += 1
                if (early_stop_count >= max_chunk_gave_up or (bom_or_sig_available and strip_sig_or_bom is False)):
                    break
        except UnicodeDecodeError as e:
            logger.log(TRACE, 'LazyStr Loading: After MD chunk decode, code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
            early_stop_count = max_chunk_gave_up
            lazy_str_hard_failure = True
        if (not lazy_str_hard_failure and is_too_large_sequence and not is_multi_byte_decoder):
            try:
                sequences[int(50000.0):].decode(encoding_iana, errors='strict')
            except UnicodeDecodeError as e:
                logger.log(TRACE, 'LazyStr Loading: After final lookup, code page %s does not fit given bytes sequence at ALL. %s', encoding_iana, str(e))
                tested_but_hard_failure.append(encoding_iana)
                continue
        mean_mess_ratio: float = (sum(md_ratios) / len(md_ratios) if md_ratios else 0.0)
        if (mean_mess_ratio >= threshold or early_stop_count >= max_chunk_gave_up):
            tested_but_soft_failure.append(encoding_iana)
            logger.log(TRACE, '%s was excluded because of initial chaos probing. Gave up %i time(s). Computed mean chaos is %f %%.', encoding_iana, early_stop_count, round(mean_mess_ratio * 100, ndigits=3))
            if (encoding_iana in ['ascii', 'utf_8', specified_encoding] and not lazy_str_hard_failure):
                fallback_entry = CharsetMatch(sequences, encoding_iana, threshold, False, [], decoded_payload)
                if encoding_iana == specified_encoding:
                    fallback_specified = fallback_entry
                elif encoding_iana == 'ascii':
                    fallback_ascii = fallback_entry
                else:
                    fallback_u8 = fallback_entry
            continue
        logger.log(TRACE, '%s passed initial chaos probing. Mean measured chaos is %f %%', encoding_iana, round(mean_mess_ratio * 100, ndigits=3))
        if not is_multi_byte_decoder:
            target_languages: List[str] = encoding_languages(encoding_iana)
        else:
            target_languages = mb_encoding_languages(encoding_iana)
        if target_languages:
            logger.log(TRACE, '{} should target any language(s) of {}'.format(encoding_iana, str(target_languages)))
        cd_ratios = []
        if encoding_iana != 'ascii':
            for chunk in md_chunks:
                chunk_languages = coherence_ratio(chunk, 0.1, (','.join(target_languages) if target_languages else None))
                cd_ratios.append(chunk_languages)
        cd_ratios_merged = merge_coherence_ratios(cd_ratios)
        if cd_ratios_merged:
            logger.log(TRACE, 'We detected language {} using {}'.format(cd_ratios_merged, encoding_iana))
        results.append(CharsetMatch(sequences, encoding_iana, mean_mess_ratio, bom_or_sig_available, cd_ratios_merged, decoded_payload))
        if (encoding_iana in [specified_encoding, 'ascii', 'utf_8'] and mean_mess_ratio < 0.1):
            logger.debug('Encoding detection: %s is most likely the one.', encoding_iana)
            if explain:
                logger.removeHandler(explain_handler)
                logger.setLevel(previous_logger_level)
            return CharsetMatches([results[encoding_iana]])
        if encoding_iana == sig_encoding:
            logger.debug('Encoding detection: %s is most likely the one as we detected a BOM or SIG within the beginning of the sequence.', encoding_iana)
            if explain:
                logger.removeHandler(explain_handler)
                logger.setLevel(previous_logger_level)
            return CharsetMatches([results[encoding_iana]])
    if len(results) == 0:
        if (fallback_u8 or fallback_ascii or fallback_specified):
            logger.log(TRACE, 'Nothing got out of the detection process. Using ASCII/UTF-8/Specified fallback.')
        if fallback_specified:
            logger.debug('Encoding detection: %s will be used as a fallback match', fallback_specified.encoding)
            results.append(fallback_specified)
        elif ((fallback_u8 and fallback_ascii is None) or (fallback_u8 and fallback_ascii and fallback_u8.fingerprint != fallback_ascii.fingerprint) or fallback_u8 is not None):
            logger.debug('Encoding detection: utf_8 will be used as a fallback match')
            results.append(fallback_u8)
        elif fallback_ascii:
            logger.debug('Encoding detection: ascii will be used as a fallback match')
            results.append(fallback_ascii)
    if results:
        logger.debug('Encoding detection: Found %s as plausible (best-candidate) for content. With %i alternatives.', results.best().encoding, len(results) - 1)
    else:
        logger.debug('Encoding detection: Unable to determine any suitable charset.')
    if explain:
        logger.removeHandler(explain_handler)
        logger.setLevel(previous_logger_level)
    return results

idna.core.valid_contextj:
def valid_contextj(label: str, pos: int) -> bool:
    cp_value = ord(label[pos])
    if cp_value == 8204:
        if pos > 0:
            if _combining_class(ord(label[pos - 1])) == _virama_combining_class:
                return True
        ok = False
        for i in range(pos - 1, -1, -1):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            if joining_type in [ord('L'), ord('D')]:
                ok = True
                break
        if not ok:
            return False
        ok = False
        for i in range(pos + 1, len(label)):
            joining_type = idnadata.joining_types.get(ord(label[i]))
            if joining_type == ord('T'):
                continue
            if joining_type in [ord('R'), ord('D')]:
                ok = True
                break
        return ok
    if cp_value == 8205:
        if pos > 0:
            if _combining_class(ord(label[pos - 1])) == _virama_combining_class:
                return True
        return False
    else:
        return False

idna.core._combining_class:
def _combining_class(cp: int) -> int:
    v = unicodedata.combining(chr(cp))
    if v == 0:
        if not unicodedata.name(chr(cp)):
            raise ValueError('Unknown character in unicodedata')
    return v

idna.core.check_bidi:
def check_bidi(label: str, check_ltr: bool = False) -> bool:
    bidi_label = False
    for (idx, cp) in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if direction == '':
            raise IDNABidiError('Unknown directionality in label {} at position {}'.format(repr(label), idx))
        if direction in ['R', 'AL', 'AN']:
            bidi_label = True
    if (not bidi_label and not check_ltr):
        return True
    direction = unicodedata.bidirectional(label[0])
    if direction in ['R', 'AL']:
        rtl = True
    elif direction == 'L':
        rtl = False
    else:
        raise IDNABidiError('First codepoint in label {} must be directionality L, R or AL'.format(repr(label)))
    valid_ending = False
    number_type = None
    for (idx, cp) in enumerate(label, 1):
        direction = unicodedata.bidirectional(cp)
        if rtl:
            if not direction in ['R', 'AL', 'AN', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError('Invalid direction for codepoint at position {} in a right-to-left label'.format(idx))
            if direction in ['R', 'AL', 'EN', 'AN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False
            if direction in ['AN', 'EN']:
                if not number_type:
                    number_type = direction
                elif number_type != direction:
                    raise IDNABidiError('Can not mix numeral types in a right-to-left label')
        else:
            if not direction in ['L', 'EN', 'ES', 'CS', 'ET', 'ON', 'BN', 'NSM']:
                raise IDNABidiError('Invalid direction for codepoint at position {} in a left-to-right label'.format(idx))
            if direction in ['L', 'EN']:
                valid_ending = True
            elif direction != 'NSM':
                valid_ending = False
    if not valid_ending:
        raise IDNABidiError('Label ends with illegal codepoint directionality')
    return True
